def _ruta(cache):
    return os.path.join(cache, "ajedrez.json")


def lee(cache):
    try:
        return json.load(open(_ruta(cache)))
    except (OSError, ValueError):
        return {"rev": 0, "partida": None}


def _limpia(p):
    if not isinstance(p, dict):
        return None
    jug = [m for m in (p.get("jugadas") or []) if isinstance(m, str) and 4 <= len(m) <= 5][:1500]
    color = "b" if p.get("color") == "b" else "w"
    try:
        nivel = max(0, min(20, int(p.get("nivel", 6))))
    except (TypeError, ValueError):
        nivel = 6
    try:
        n = max(1, min(100000, int(p.get("n") or 1)))
    except (TypeError, ValueError):
        n = 1
    res = p.get("resultado")
    out = {"jugadas": jug, "fen": str(p.get("fen") or "")[:100], "color": color, "nivel": nivel,
           "turno": "b" if p.get("turno") == "b" else "w", "resultado": str(res)[:60] if res else None,
           "n": n}
    if p.get("motor") == "propio":
        out["motor"] = "propio"
    return out


JUEGOS = ("damas", "conecta4", "go", "jarrones")
LONG = {"damas": 64, "conecta4": 42, "go": 81, "jarrones": 50}


def _ent(v, a, b, d=0):
    if type(v) is not int:
        return d
    return max(a, min(b, v))


def _lista_int(v, n, a, b):
    if not isinstance(v, list) or len(v) != n or not all(type(x) is int and a <= x <= b for x in v):
        return None
    return v


def _num(v, a, b):
    return type(v) in (int, float) and v == v and a <= v <= b and v not in (float("inf"), float("-inf"))


def _lista_de(v, mx, esquema):
    if not isinstance(v, list) or len(v) > mx:
        return None
    for z in v:
        if not isinstance(z, list) or len(z) != len(esquema):
            return None
        for x, (a, b, ent) in zip(z, esquema):
            if not _num(x, a, b) or (ent and type(x) is not int):
                return None
    return v


def _limpia_estado_jarrones(est):
    if est.get("v") != 6 or type(est.get("v")) is not int:
        return None
    tab = _lista_int(est.get("tab"), 50, 0, 59)
    if tab is None:
        return None
    for x in tab:
        k, c = x % 20, x // 20
        if x and (k < 4 or k > 15 or k == 6 or c > 2 or (c == 0 and k == 13) or (c == 1 and k not in (4, 5, 7, 8, 9)) or (c == 2 and k != 13)):
            return None
    pl = _lista_de(est.get("pl"), 50, [(0, 10 ** 9, True), (0, 4, True), (0, 9, True), (4, 9, True), (-99, 99, False), (-20, 99, False), (0, 10, False)])
    zs = _lista_de(est.get("zs"), 80, [(0, 10 ** 9, True), (0, 4, True), (-1, 12, False), (1, 6, True), (-999, 999, False), (0, 10, False), (0, 10, False)])
    gs = _lista_de(est.get("gs"), 200, [(0, 10 ** 9, True), (0, 4, True), (-1, 12, False), (0, 1, True), (-1, 1, True)])
    if gs is not None and any(g[4] == 0 for g in gs):
        return None
    vu = _lista_de(est.get("vu"), 20, [(0, 10 ** 9, True), (0, 4, True), (-1, 5, False), (-1, 12, False)])
    ent = _lista_de(est.get("ent"), 80, [(0, 10 ** 6, False), (0, 4, True), (1, 3, True)])
    fl = _lista_de(est.get("fl"), 50, [(0, 10 ** 9, True), (0, 4, True), (1, 9, True), (4, 15, True), (-99, 99, False)])
    sp = _lista_de(est.get("sp", []), 50, [(0, 10 ** 9, True), (-1, 20, False), (4, 9, True)])
    vit = est.get("vit", 0)
    if pl is None or zs is None or gs is None or vu is None or ent is None or fl is None or sp is None or type(vit) is not int or not 0 <= vit <= 5:
        return None
    t, pausa = est.get("t"), est.get("pausa")
    if not _num(t, 0, 10 ** 7) or not _num(pausa, 0, 10):
        return None
    return {"v": 6, "tab": tab, "pl": pl, "zs": zs, "gs": gs, "vu": vu, "ent": ent, "fl": fl, "vit": vit, "sp": sp, "turno": 1, "t": t, "pausa": pausa,
            "sol": _ent(est.get("sol"), 0, 10 ** 6), "ronda": _ent(est.get("ronda"), 1, 100000, 1), "rec": _ent(est.get("rec"), 1, 100000, 1),
            "pid": _ent(est.get("pid"), 0, 10 ** 9), "zid": _ent(est.get("zid"), 0, 10 ** 9), "gid": _ent(est.get("gid"), 0, 10 ** 9),
            "rs": _ent(est.get("rs"), -2147483648, 2147483647), "fin": "perdida" if est.get("fin") == "perdida" else None}


def _limpia_j(p, juego):
    if not isinstance(p, dict) or not isinstance(p.get("est"), dict):
        return None
    est = p["est"]
    tab = est.get("tab")
    lo = 0 if juego == "go" else -2
    if juego == "jarrones":
        e = _limpia_estado_jarrones(est)
        if e is None:
            return None
    elif not isinstance(tab, list) or len(tab) != LONG[juego] or not all(isinstance(x, int) and lo <= x <= 2 for x in tab):
        return None
    else:
        e = {"tab": tab}
    if juego == "jarrones":
        pass
    elif juego == "go":
        def ent(k, a, b, d=0):
            try:
                return max(a, min(b, int(est.get(k) if est.get(k) is not None else d)))
            except (TypeError, ValueError):
                return d
        e["turno"] = 2 if est.get("turno") == 2 else 1
        e["pasos"] = ent("pasos", 0, 2)
        e["ko"] = ent("ko", -1, 80, -1)
        e["capN"] = ent("capN", 0, 1000)
        e["capB"] = ent("capB", 0, 1000)
        e["n"] = ent("n", 0, 1000)
    elif juego == "damas":
        e["turno"] = "b" if est.get("turno") == "b" else "w"
        e["sin"] = max(0, min(1000, int(est.get("sin") or 0)))
    else:
        e["turno"] = 2 if est.get("turno") == 2 else 1
        e["n"] = max(0, min(42, int(est.get("n") or 0)))
    hist = p.get("hist")
    hist = hist[-400:] if isinstance(hist, list) else []
    if juego == "go":
        hist = [x for x in hist if type(x) is int and -1 <= x <= 80]
    elif juego == "jarrones":
        hist = [x for x in hist if type(x) is int and -1 <= x <= 44]
    ult = p.get("ult") if isinstance(p.get("ult"), (dict, int)) or p.get("ult") is None else None
    try:
        nivel = max(0, min(20, int(p.get("nivel", 6))))
        n = max(1, min(100000, int(p.get("n") or 1)))
    except (TypeError, ValueError):
        nivel, n = 6, 1
    color = p.get("color")
    color = ("b" if color == "b" else "w") if juego == "damas" else (2 if color == 2 and juego != "jarrones" else 1)
    res = p.get("resultado")
    out = {"est": e, "hist": hist, "color": color, "nivel": nivel, "resultado": str(res)[:60] if res else None, "n": n, "ult": ult}
    if len(json.dumps(out)) > 40000:
        return None
    return out


def guarda(cache, d):
    p = _limpia(d.get("partida"))
    if p is None:
        return {"error": "partida inválida"}
    js = {}
    if isinstance(d.get("juegos"), dict):
        for k in JUEGOS:
            q = _limpia_j(d["juegos"].get(k), k)
            if q is not None:
                js[k] = q
    juego = d.get("juego") if d.get("juego") in ("ajedrez",) + JUEGOS else "ajedrez"
    with _cerrojo:
        act = lee(cache)
        try:
            base = int(d.get("base"))
        except (TypeError, ValueError):
            base = act["rev"]
        js = {**(act.get("juegos") or {}), **js}
        if base < act["rev"]:
            return {"conflicto": True, **act}
        nuevo = {"rev": act["rev"] + 1, "t": int(time.time()), "partida": p, "juego": juego}
        if js:
            nuevo["juegos"] = js
        ruta, tmp = _ruta(cache), _ruta(cache) + ".tmp%d" % os.getpid()
        os.makedirs(cache, exist_ok=True)
        with open(tmp, "w") as f:
            json.dump(nuevo, f)
        os.replace(tmp, ruta)
        return nuevo


def estatico(nombre, aqui):
    e = ESTATICOS.get(nombre)
    if not e:
        return None
    try:
        return open(os.path.join(aqui if e[0] == "aqui" else LIBS, nombre), "rb").read(), e[1]
    except OSError:
        return None
